//! Immutable semantic definitions and typed values.

use std::collections::BTreeMap;
use std::marker::PhantomData;
use std::sync::Arc;

use serde::{Serialize, de::DeserializeOwned};

use crate::error::{Error, ErrorCode};
use crate::raw::{ApiName, Key, ObjectType as RawObjectType, Record, Revision, Spec, Value};

/// A Rust value with a semantic object definition.
pub trait Object: Sized + Send + Sync + 'static {
    /// Primary-key Rust type.
    type Key: Serialize + DeserializeOwned + Clone + std::fmt::Debug + Send + Sync + 'static;
    /// Semantic definition generated by `#[derive(Object)]`.
    fn definition() -> RawObjectType;
    /// Primary key of this value.
    fn key(&self) -> Result<Self::Key, Error>;
    /// Encode this value for the engine boundary.
    fn encode(&self) -> Result<BTreeMap<ApiName, Value>, Error>;
    /// Decode one engine record.
    fn decode(record: Record) -> Result<Self, Error>;
    /// Stable semantic API name.
    fn api_name() -> ApiName {
        Self::definition().api_name
    }
    /// Encode one field without encoding the whole value.
    ///
    /// Lets a scan evaluate a filter against the fields it names and encode
    /// only the rows it returns. `#[derive(Object)]` generates a direct
    /// implementation; the default encodes everything.
    #[doc(hidden)]
    fn encode_field(&self, name: &ApiName) -> Result<Option<Value>, Error> {
        Ok(self.encode()?.remove(name))
    }
}

/// A typed semantic relationship.
pub trait Link: Send + Sync + 'static {
    /// Source object type.
    type Source: Object;
    /// Target object type.
    type Target: Object;
    /// Semantic link definition.
    fn definition() -> crate::raw::LinkType;
}

/// Reusable semantic property definition.
pub trait Trait: Send + Sync + 'static {
    /// Semantic trait definition.
    fn definition() -> crate::raw::Trait;
}

/// A typed semantic command.
pub trait Action: Sized + Send + Sync + 'static {
    /// Successful output.
    type Output: Send + Sync + 'static;
    /// Semantic action definition.
    fn definition() -> crate::raw::ActionType;
    /// Encode the command input.
    fn encode(&self) -> Result<Value, Error>;
    /// Decode an input received by a bound handler.
    fn decode_input(value: Value) -> Result<Self, Error>;
    /// Decode the successful output.
    fn decode(value: Option<Value>) -> Result<Self::Output, Error>;
    /// Encode a handler output.
    fn encode_output(value: &Self::Output) -> Result<Value, Error>;
}

/// One typed result page.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Page<T> {
    /// Materialized values.
    pub items: Vec<T>,
    /// Opaque cursor for the next page.
    pub next_cursor: Option<String>,
}

impl<T> IntoIterator for Page<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        self.items.into_iter()
    }
}

/// Public view of the runtime's compiled semantic schema.
#[derive(Clone)]
pub struct Schema(pub(crate) Arc<Spec>);

impl Schema {
    /// Number of object definitions.
    #[must_use]
    pub fn object_count(&self) -> usize {
        self.0.object_types.len()
    }

    /// Semantic object names in declaration order.
    pub fn objects(&self) -> impl ExactSizeIterator<Item = &str> {
        self.0
            .object_types
            .iter()
            .map(|item| item.api_name.as_str())
    }

    /// Semantic link names in declaration order.
    pub fn links(&self) -> impl ExactSizeIterator<Item = &str> {
        self.0.link_types.iter().map(|item| item.api_name.as_str())
    }

    /// Semantic action names in declaration order.
    pub fn actions(&self) -> impl ExactSizeIterator<Item = &str> {
        self.0.actions.iter().map(|item| item.api_name.as_str())
    }
}

/// Advanced execution result with provenance and concurrency metadata.
#[derive(Debug, Clone)]
pub struct Execution<T> {
    /// Useful operation result.
    pub value: T,
    /// Engine execution receipt.
    pub receipt: crate::raw::ExecutionReceipt,
    /// Backend revision when the operation produced one record.
    pub revision: Option<Revision>,
}

/// Result of an atomic batch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BatchResult {
    /// Number of affected rows when the backend reports it.
    pub rows_affected: Option<i64>,
}

/// Semantic aggregation rows.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AggregationResult {
    /// Group keys and aggregate aliases.
    pub groups: Vec<BTreeMap<String, Value>>,
}

/// Type-safe field descriptor generated for an object.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Field<O, T> {
    name: &'static str,
    marker: PhantomData<fn() -> (O, T)>,
}

impl<O, T> Field<O, T> {
    /// Construct a generated field descriptor.
    #[doc(hidden)]
    #[must_use]
    pub const fn new(name: &'static str) -> Self {
        Self {
            name,
            marker: PhantomData,
        }
    }
    /// Semantic property name.
    #[must_use]
    pub fn name(self) -> ApiName {
        ApiName::new_unchecked(self.name)
    }
}

/// Build a name once per call site and share it afterwards.
#[doc(hidden)]
pub fn cached_name(cell: &std::sync::OnceLock<ApiName>, name: &str) -> ApiName {
    cell.get_or_init(|| ApiName::new_unchecked(name)).clone()
}

#[doc(hidden)]
pub fn encode_value<T: Serialize>(value: &T) -> Result<Value, Error> {
    serde_json::to_value(value)
        .map(Value::new)
        .map_err(|error| Error::bad_request(error.to_string()))
}

#[doc(hidden)]
pub fn decode_value<T: DeserializeOwned>(value: Option<Value>, field: &str) -> Result<T, Error> {
    let value = value.map_or(serde_json::Value::Null, Into::into);
    serde_json::from_value(value).map_err(|error| {
        Error::new(
            ErrorCode::Validation,
            format!("invalid field '{field}': {error}"),
        )
    })
}

#[doc(hidden)]
pub fn encode_key<T: Serialize>(value: &T) -> Result<Key, Error> {
    Key::identity(&encode_value(value)?).map_err(|error| Error::bad_request(error.to_string()))
}
